"""
Module for managing cache statistics in clang-tidy-cache.
"""

import os
import sys
import time
import gzip
import json
import logging

# ------------------------------------------------------------------------------
class CacheStats:
    """Class to manage and expose cache statistics."""
    # --------------------------------------------------------------------------
    def __init__(
        self,
        save_path: str,
        save_interval: float = 3600.0,
        stats_save_interval: float = 3600.0
    ):
        self._log = logging.getLogger(__name__)
        self._start_time = time.time()
        self._cleaned_count = 0
        self._hits_count = 0
        self._miss_count = 0
        self._cached = {}
        self._stats = []
        self._save_path = save_path
        self._save_interval = save_interval
        self._stats_save_interval = stats_save_interval
        self._stats_save_time = time.time()
        self._save_time = time.time()
        self._cleanup_time = time.time()

    # --------------------------------------------------------------------------
    def uptime_seconds(self) -> float:
        return time.time() - self._start_time

    # --------------------------------------------------------------------------
    def saved_seconds_ago(self) -> float:
        return time.time() - self._save_time

    # --------------------------------------------------------------------------
    def saved_stats_seconds_ago(self) -> float:
        return time.time() - self._stats_save_time

    # --------------------------------------------------------------------------
    def cleaned_seconds_ago(self) -> float:
        return time.time() - self._cleanup_time

    # --------------------------------------------------------------------------
    def total_hit_rate(self) -> float:
        total = self._hits_count + self._miss_count
        if total == 0:
            return 0.0
        return self._hits_count / total

    # --------------------------------------------------------------------------
    def hit_count(self) -> int:
        return self._hits_count

    # --------------------------------------------------------------------------
    def hit_rate(self) -> float:
        return self.total_hit_rate()

    # --------------------------------------------------------------------------
    def miss_count(self) -> int:
        return self._miss_count

    # --------------------------------------------------------------------------
    def miss_rate(self) -> float:
        return 1.0 - self.total_hit_rate()

    # --------------------------------------------------------------------------
    def cached_count(self) -> int:
        return len(self._cached)

    # --------------------------------------------------------------------------
    def cleaned_count(self) -> int:
        return self._cleaned_count

    # --------------------------------------------------------------------------
    def save_file_size(self) -> int:
        try:
            return os.path.getsize(self._save_path)
        except OSError:
            return 0

    # --------------------------------------------------------------------------
    def save_cache_size(self) -> int:
        return sum(info.get("size", 0) for info in self._cached.values())

    # --------------------------------------------------------------------------
    def age_days_histogram(self) -> dict:
        now = time.time()
        histogram = {}
        for info in self._cached.values():
            age_days = int((now - info.get("insert_time", now)) / (24 * 3600))
            histogram[age_days] = histogram.get(age_days, 0) + 1
        return histogram

    # --------------------------------------------------------------------------
    def hit_count_histogram(self) -> dict:
        histogram = {}
        for info in self._cached.values():
            hits = info.get("hits", 0)
            histogram[hits] = histogram.get(hits, 0) + 1
        return histogram

    # --------------------------------------------------------------------------
    def get_stats(self) -> dict:
        return {
            "uptime_seconds": self.uptime_seconds(),
            "saved_size_bytes": self.save_file_size(),
            "saved_cache_size": self.save_cache_size(),
            "saved_seconds_ago": self.saved_seconds_ago(),
            "cleaned_seconds_ago": self.cleaned_seconds_ago(),
            "total_hit_rate": self.total_hit_rate(),
            "hit_count": self.hit_count(),
            "hit_rate": self.hit_rate(),
            "miss_count": self.miss_count(),
            "miss_rate": self.miss_rate(),
            "cached_count": self.cached_count(),
            "cleaned_count": self.cleaned_count(),
            "age_days_histogram": self.age_days_histogram(),
            "hit_count_histogram": self.hit_count_histogram()
        }

    # --------------------------------------------------------------------------
    def increment_hits(self, count: int = 1) -> None:
        self._hits_count += count

    # --------------------------------------------------------------------------
    def increment_misses(self, count: int = 1) -> None:
        self._miss_count += count

    # --------------------------------------------------------------------------
    def register_cache_entry(self, hashstr: str, info: dict) -> None:
        self._cached[hashstr] = info

    # --------------------------------------------------------------------------
    def unregister_cache_entry(self, hashstr: str) -> None:
        if hashstr in self._cached:
            del self._cached[hashstr]

    # --------------------------------------------------------------------------
    def set_cleaned_count(self, count: int) -> None:
        self._cleaned_count = count
